"""Writes pew_tables.h: the sine pew.c builds its drawbar tables from (block rate, pew.c build()) and its LFOs read."""
import math, os
N = 1024
v = [round(32767 * math.sin(2 * math.pi * i / N)) for i in range(N + 1)]
out = ["/* Copyright (C) 2026 Hundekraft. GPL-3.0-or-later with the OP-1 firmware permission (see LICENSE and NOTICE). */",
       "/* generated by gen_tables.py */", "#include <stdint.h>", f"#define PW_SIZE {N}",
       "static const int16_t pw_sin[PW_SIZE + 1] = {"]
out += ["    " + ", ".join(str(x) for x in v[i:i + 16]) + "," for i in range(0, N + 1, 16)]
out += ["};", ""]
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "pew_tables.h"), "w").write("\n".join(out))
